let ctx,enabled=localStorage.getItem('mq.sound')!=='off',music=localStorage.getItem('mq.music')!=='off',master,musicBus,lastResume=0,nextBeat=0,step=0,mode='',lastKey='',lastSecond=-1,lastResultCue=-1,noiseBuffer=null;
export function soundEnabled(){return enabled;}
