export function playSound(type){if(!enabled||!ctx||ctx.state!=='running')return;const notes={correct:[523,659,784,1047],wrong:[330,247],timeout:[294,220],finish:[392,523,659,784,1047],start:[392,523,659],click:[660],tick:[880],urgent:[1047],points:[440,554,659],rank:[659,784,1047],timeup:[196,147],lock:[392,587],intro:[392,523,659,784],reveal:[330,392,523,784]}[type];if(!notes)return;const now=ctx.currentTime;notes.forEach((f,i)=>tone(f,now+i*.095,type==='tick'||type==='urgent'?.08:.19,type==='urgent'?.12:.085,type==='urgent'?'triangle':'sine'));if(type==='finish'||type==='rank')applause(now+.18,type==='finish');if(type==='reveal'){for(let i=0;i<7;i++)noise(now+i*.06,.05,.08,1500+i*100);}if(type==='lock')noise(now,.055,.025,2400);}
