export function updateShowAudio(state,offset=0){if(!state){if(musicBus&&ctx)musicBus.gain.setTargetAtTime(0,ctx.currentTime,.06);mode='';lastKey='';return;}unlockAudio();if(!ctx||ctx.state!=='running')return;const now=ctx.currentTime,remaining=state.phase==='question'&&state.deadline?Math.max(0,state.deadline-Date.now()-offset):null,second=remaining===null?-1:Math.ceil(remaining/1000),key=[state.matchId,state.index,state.phase,state.partyStage].join(':');if(key!==lastKey){lastKey=key;lastSecond=-1;lastResultCue=-1;}if(state.phase==='question'&&state.partyStage!=='reflex-wait'&&second!==lastSecond){if(second>=1&&second<=5)playSound(second<=3?'urgent':'tick');if(second===0&&lastSecond>0)playSound('timeup');lastSecond=second;}if(state.phase==='reveal'){const elapsed=Date.now()+offset-(state.revealStarted||Date.now());const cue=elapsed>=5200?2:elapsed>=2200?1:0;if(cue!==lastResultCue){if(cue===0&&elapsed<800)playSound('reveal');if(cue===1)playSound('points');if(cue===2)playSound('rank');lastResultCue=cue;}}
const next=state.phase==='question'&&state.kind==='arcade'?'arcade':state.phase==='question'&&second>=1&&second<=5&&state.partyStage!=='reflex-wait'?'urgent':state.phase==='question'?'question':patterns[state.phase]?state.phase:'lobby';if(next!==mode){mode=next;step=0;nextBeat=now+.03;}const volume=music?(state.question?.media&&state.phase==='question'?0:second>=1&&second<=5?.028:next==='reveal'?.065:.08):0;musicBus.gain.setTargetAtTime(volume,now,.12);if(!music||!volume){nextBeat=now+.04;return;}if(nextBeat<now-.2)nextBeat=now+.03;const duration=next==='urgent'?.17:next==='arcade'?.21:next==='question'?.28:.25;const seq=patterns[next==='urgent'?'question':next];while(nextBeat<now+.22){const note=seq[step%seq.length];tone(hz(note),nextBeat,duration*.88,.30,step%4===0?'triangle':'sine',musicBus);if(step%4===0){tone(hz(note-12),nextBeat,duration*2,.38,'sine',musicBus);tone(90,nextBeat,.09,.28,'triangle',musicBus);if(next==='lobby'||next==='finished')tone(hz(note+7),nextBeat,duration*1.8,.13,'triangle',musicBus);}if(step%4===2)noise(nextBeat,.075,.19,1900,musicBus);if(step%2===1)noise(nextBeat,.035,.055,4800,musicBus);step++;nextBeat+=duration;}}
export function confetti(parent){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=document.createElement('div');box.className='mq-confetti';box.setAttribute('aria-hidden','true');for(let i=0;i<30;i++){const p=document.createElement('i');p.style.setProperty('--x',((i*37)%100)+'%');p.style.setProperty('--delay',(i%7)*.045+'s');p.style.setProperty('--spin',((i%2?1:-1)*(120+i*11))+'deg');p.style.background=['#f8d64d','#ff6685','#65b6ff','#6ee5a3'][i%4];box.append(p);}parent.append(box);setTimeout(()=>box.remove(),1500);}
